const ekko = loadGz(path.join(root,'参考资料/客户端原文/Ekko.json.gz'));
const fizz = loadGz(path.join(root,'参考资料/客户端原文/Fizz.json.gz'));

function pickSpell(obj) {
  const s = obj.mSpell || {};
  return {
    ObjectName: obj.ObjectName,
    mScriptName: obj.mScriptName,
    spellCastTime: s.spellCastTime ?? null,
    mCastTime: s.mCastTime ?? null,
    delayCastOffsetPercent: s.delayCastOffsetPercent ?? null,
    delayTotalTimePercent: s.delayTotalTimePercent ?? null,
    mChannelDuration: s.mChannelDuration ?? null,
    mChargeUpdateInterval: s.mChargeUpdateInterval ?? null,
    cooldownTime: s.cooldownTime ?? null,
    mana: s.mana ?? null,
    mAlternateName: s.mAlternateName ?? null,
    DataValues: (s.DataValues||[]).map(dv => ({name: dv.name, values: dv.values, mValues: dv.mValues})),
    calculations: s.mSpellCalculations || null,
    mLocKeys: s.mClientData?.mTooltipData?.mLocKeys || null,
    mImgIconName: s.mImgIconName ?? null,
    mSpellTags: s.mSpellTags ?? null,
    mBuff: obj.mBuff || null,
  };
}

const out = {ekko:{}, fizz:{}};
for (const [k,v] of Object.entries(ekko)) {
  if (k.startsWith('Characters/Ekko/Spells') && v && typeof v === 'object') {
    if (v.mSpell || v.mBuff) out.ekko[k] = pickSpell(v);
  }
}
for (const [k,v] of Object.entries(fizz)) {
  if (k.startsWith('Characters/Fizz/Spells') && v && typeof v === 'object') {
    if (v.mSpell || v.mBuff) out.fizz[k] = pickSpell(v);
  }
}
console.log(JSON.stringify(out, null, 2));
